import{_ as o,a as i,b as t}from"./chunks/Desktop_Build.CQHeU67k.js";import{_ as l,o as d,c as r,ag as a}from"./chunks/framework.D9ghT4bC.js";const b=JSON.parse('{"title":"本地构建","description":"","frontmatter":{},"headers":[],"relativePath":"zh/Developers/Building-Locally.md","filePath":"zh/Developers/Building-Locally.md"}'),n={name:"zh/Developers/Building-Locally.md"};function c(u,e,s,p,h,m){return d(),r("div",null,[...e[0]||(e[0]=[a('<h1 id="本地构建" tabindex="-1">本地构建 <a class="header-anchor" href="#本地构建" aria-label="Permalink to &quot;本地构建&quot;">​</a></h1><p>读完本指南，你将能够从代码本地运行 Unciv，从而做出修改并在本地测试。</p><h2 id="使用-android-studio" tabindex="-1">使用 Android Studio <a class="header-anchor" href="#使用-android-studio" aria-label="Permalink to &quot;使用 Android Studio&quot;">​</a></h2><ul><li>安装 <a href="https://developer.android.com/studio" target="_blank" rel="noreferrer">Android Studio</a> - 免费且超棒！注意下载量很大！</li><li>安装 Git，这是我们协作的方式。UI 可选，Android Studio 内置的 Git 工具就很好用 😃</li><li>获取代码 <ul><li>创建一个 <a href="https://github.com/join" target="_blank" rel="noreferrer">Github 账户</a>，如果还没有的话</li><li><a href="https://github.com/yairm210/Unciv/fork" target="_blank" rel="noreferrer">Fork 仓库</a> - 这会在你的账户下创建一份代码&quot;副本&quot;，位于 <code>https://github.com/&lt;你的用户名&gt;/Unciv</code></li></ul></li><li>在 Android Studio 中加载项目 <ul><li>File -&gt; New -&gt; Project from Version Control -&gt; GitHub</li><li>输入你的 GitHub 用户名和密码</li><li>选择仓库并点击克隆 - GitHub 仓库会作为新项目创建在 Android Studio 中。</li></ul></li><li>Gradle 会尝试初始同步。如果你是第一次用 Android Studio，可能需要接受 Android Build-tools 许可证，不同设备上操作方式不同，请搜索你所用系统的解决方案。 <ul><li>新安装可能无法完成初始同步 - 错误形式是 <code>Unable to find method &#39;&#39;void org.apache.commons.compress.archivers.zip.ZipFile.&lt;init&gt;(java.nio.channels.SeekableByteChannel)&#39;&#39;</code>。如果遇到这个问题，进入 File &gt; Settings &gt; Languages &amp; Frameworks &gt; Android SDK <ul><li>点击 &quot;SDK Platforms&quot;</li><li>点击 &quot;Android 16.0 (&quot;Baklava&quot;)&quot; <img src="'+o+'" alt="image"> （可选：勾选 &#39;Show Package Details&#39; 只选 Platform SDK，不带 Sources 或系统镜像，可以省点空间）</li><li>点击 &quot;SDK Tools&quot;</li><li>在右下角选择 &quot;Show Package Details&quot;</li><li>在 &quot;Android SDK Build-Tools&quot; 下选择版本 35.0.0 <img src="'+i+'" alt="image"></li><li>点击 &quot;Apply&quot;</li><li>重启 Android Studio</li></ul></li></ul></li><li>耐心等待初始 Gradle 同步完成。之后的同步不会这么慢。留意状态栏或 &quot;Build&quot; 工具窗格。</li><li>如果一切顺利，你现在会有三个 &quot;运行配置&quot;（看顶栏绿色的）：&quot;android&quot;、&quot;Desktop&quot; 和 &quot;Run unit tests&quot;。 <ul><li>如果 &quot;android&quot; 缺失，很可能是你的 Android SDK 配置没有设置 ANDROID_HOME 环境变量。设置它，重启 Studio 并重新同步 Gradle（顶栏那个大象加箭头的按钮）。</li><li>如果 &quot;Desktop&quot; 缺失，手动创建一个： <ul><li>选择 Run &gt; Edit configurations（从主菜单或配置下拉框）</li><li>点击 &quot;+&quot; 添加新配置</li><li>选择 &quot;Application&quot;</li><li>给配置起个名字，我们建议 &quot;Desktop&quot;</li><li>把模块类路径（Java 选择框右侧的框）设为 <code>Unciv.desktop.main</code>（Bumblebee 及以下版本为 <code>Unciv.desktop</code>），主类设为 <code>com.unciv.app.desktop.DesktopLauncher</code>，工作目录设为 <code>$ProjectFileDir$/android/assets</code>，点 OK 关闭窗口 <ul><li>设置一些 VM 选项可能有用——在运行配置编辑器中用 Alt-V 或通过 Modify Options 菜单激活该字段，然后加 <code>-Xmx4096m -Xms256m -XX:MaxMetaspaceSize=256m</code> 给调试中的游戏多一点内存。或者用 <code>-DnoLog=</code> 或 <code>-DonlyLog=</code> 选项控制控制台日志。详见 <a href="https://github.com/yairm210/Unciv/blob/master/core/src/com/unciv/utils/Log.kt" target="_blank" rel="noreferrer">Log.kt</a> 的注释。</li><li>如果出现 <code>../../docs/uniques.md (No such file or directory)</code> 错误，说明你忘了设置工作目录！ <img src="'+t+'" alt="image"></li></ul></li></ul></li><li>如果 &quot;Run unit tests&quot; 缺失 - 找到顶层的 &quot;tests&quot; 文件夹，右键 -&gt; Modify Run Configuration...</li></ul></li><li>选择 Desktop 配置（或你起的其他名字），点击绿色箭头运行！或者用旁边的按钮——那只六条腿两只触角的小虫子——开始调试。</li><li>一些推荐的 Android Studio 设置： <ul><li>进入 Settings &gt; Version Control &gt; Commit &gt; Advanced Commit，关闭 &#39;Analyze code&#39;</li><li>同一页面，建议关闭 &quot;Use non-modal commit interface&quot;。这会把 &quot;Local Changes&quot; 和 &quot;Console&quot; 标签放回 Git 工具窗格（以及做 shelf 后的 Shelf）。这些可能很难找——如果觉得不需要可以忽略。</li><li>Settings &gt; Editor &gt; Code Style &gt; Kotlin &gt; Tabs and Indents &gt; Continuation Indent: 4 <img src="https://user-images.githubusercontent.com/44038014/169315352-9ba0c4cf-307c-44d1-b3bc-2a58752c6854.png" alt="image"></li><li>Settings &gt; Editor &gt; General &gt; On Save &gt; 取消勾选 Remove trailing spaces on: [...] 防止它移除 template.properties 翻译文件中必要的尾随空格 <img src="https://user-images.githubusercontent.com/44038014/169316243-07e36b8e-4c9e-44c4-941c-47e634c68b4c.png" alt="image"><blockquote><p>重要：取消勾选会产生烦人的合并冲突。提交（非翻译文件）前移除那些尾随空格。更多信息见<a href="https://yairm210.github.io/Unciv/Developers/Coding-standards/" target="_blank" rel="noreferrer">代码标准</a>。（UncivCN 分支文档站为 VitePress，中文版见 <a href="/Unciv/zh/Developers/Coding-standards.html">/zh/Developers/Coding-standards</a>。）</p></blockquote></li><li>右键点击 <code>android/assets/SaveFiles</code> 文件夹（一旦你有了它），&quot;Mark directory as&quot; &gt; Excluded <ul><li>如果下载了模组，对 <code>android/assets/mods</code> 文件夹以及你创建的不属于公共项目的任何其他文件也这样做。</li><li>这会<a href="https://www.jetbrains.com/help/idea/indexing.html#exclude" target="_blank" rel="noreferrer">禁用索引</a>以提升性能。</li></ul></li></ul></li></ul><p>Unciv 用 Gradle 来指定依赖和运行方式。在后台，Gradle 小精灵们会去取包（一次性工作），完成后就会构建项目！</p><p>Unciv 使用 Gradle 8.11.1 和 Android Gradle Plugin 8.9.1。可以在 File &gt; Project Structure &gt; Project 中查看。</p><blockquote><p>注意：高级构建命令（如下一段所述），特别是 <code>gradlew desktop:dist</code> 构建 jar，在 Android Studio 的终端（Alt+F12）里运行完全没有问题，大部分依赖已经就绪。</p></blockquote><h2 id="不用-android-studio" tabindex="-1">不用 Android Studio <a class="header-anchor" href="#不用-android-studio" aria-label="Permalink to &quot;不用 Android Studio&quot;">​</a></h2><ul><li>确保已安装 JDK 11 或更高版本</li><li>克隆项目（见上面的初始步骤）</li><li>在 Unciv 文件夹打开终端，运行以下命令</li></ul><h3 id="windows-cmd" tabindex="-1">Windows (CMD) <a class="header-anchor" href="#windows-cmd" aria-label="Permalink to &quot;Windows (CMD)&quot;">​</a></h3><ul><li>运行：<code>gradlew desktop:run</code></li><li>构建：<code>gradlew desktop:dist</code></li></ul><h3 id="linux-macos-windows-powershell" tabindex="-1">Linux / macOS / Windows (PowerShell) <a class="header-anchor" href="#linux-macos-windows-powershell" aria-label="Permalink to &quot;Linux / macOS / Windows (PowerShell)&quot;">​</a></h3><ul><li>运行：<code>./gradlew desktop:run</code></li><li>构建：<code>./gradlew desktop:dist</code></li></ul><p>如果 Mac/Linux 上终端返回 <code>Permission denied</code> 或 <code>Command not found</code>，先运行 <code>chmod +x ./gradlew</code>。<em>这是一次性操作。</em></p><p>如果报错找不到 Android SDK 文件夹，运行下面的命令安装：</p><p><code>sudo apt update &amp;&amp; sudo apt install android-sdk</code>（Debian、Ubuntu、Mint 等）</p><p>然后，在 <code>local.properties</code> 文件中设置 SDK 位置，添加：</p><p><code>sdk.dir = /path/to/android/sdk</code> - 例如 <code>/usr/lib/android-sdk</code></p><p>如果启动时报 JDK 版本错误，从<a href="https://adoptium.net/temurin/releases/" target="_blank" rel="noreferrer">这里</a>安装 JDK。</p><blockquote><p>注意：Gradle 可能需要几分钟下载文件 构建完成后，输出的 .JAR 文件应该在 <code>/desktop/build/libs/Unciv.jar</code></p></blockquote><p>要进行实际开发，你可能需要下载 Android Studio 自己构建——见上文 😃</p><h2 id="在-android-上调试" tabindex="-1">在 Android 上调试 <a class="header-anchor" href="#在-android-上调试" aria-label="Permalink to &quot;在 Android 上调试&quot;">​</a></h2><p>有时桌面版调试不够，你需要在 Android 设备上调试 Unciv。 介绍见 <a href="./Testing-Android-Builds.html">测试 Android 构建</a>。</p><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><p>恭喜！Unciv 现在应该已经在你的电脑上运行了！现在我们可以开始改代码了，之后再看你的改动如何进入主仓库！</p><p>现在是个好时机去了解<a href="./Project-structure-and-major-classes.html">项目结构总览！</a></p><h3 id="单元测试" tabindex="-1">单元测试 <a class="header-anchor" href="#单元测试" aria-label="Permalink to &quot;单元测试&quot;">​</a></h3><p>你可以（有些情况下<em>应该</em>）在本地运行甚至调试单元测试。</p><ul><li>仓库包含一个 &quot;Run unit tests&quot; 运行配置。如果缺失：</li><li>在 Android Studio 中，Run &gt; Edit configurations。 <ul><li>点击 &quot;+&quot; 添加新配置</li><li>选择 &quot;Gradle&quot; 并命名为 &quot;Run unit tests&quot;</li><li>在 &quot;Gradle Project&quot; 下从下拉框选择 &quot;Unciv&quot;（或直接输入），把 &quot;Tasks&quot; 设为 <code>:tests:test</code>，&quot;Arguments&quot; 设为 <code>--tests &quot;com.unciv.*&quot;</code>，点 OK 关闭窗口。</li></ul></li><li>选择 &quot;Run unit tests&quot; 配置，点击绿色箭头运行！或者像上面那样开始调试会话。</li></ul><h3 id="lint-检查" tabindex="-1">Lint 检查 <a class="header-anchor" href="#lint-检查" aria-label="Permalink to &quot;Lint 检查&quot;">​</a></h3><p>Detekt 检查代码异味和其他 lint 问题。 要生成 Detekt 报告：</p><ul><li>下载 <a href="https://github.com/detekt/detekt/releases/latest" target="_blank" rel="noreferrer">detekt-cli</a>（zip 文件）并解压</li><li>在 Unciv 根目录打开终端，运行以下命令之一生成报告。注意：Windows 下把 <code>detekt-cli</code> 换成 <code>detekt-cli.bat</code>。 <ul><li>警告：<code>PATH/TO/DETEKT/detekt-cli --parallel --report html:detekt/reports.html --config .github/workflows/detekt_config/detekt-warnings.yml</code></li><li>错误：<code>PATH/TO/DETEKT/detekt-cli --parallel --report html:detekt/reports.html --config .github/workflows/detekt_config/detekt-errors.yml</code></li></ul></li><li>报告生成在 <code>detekt/reports.html</code></li></ul><h3 id="测试文档站改动" tabindex="-1">测试文档站改动 <a class="header-anchor" href="#测试文档站改动" aria-label="Permalink to &quot;测试文档站改动&quot;">​</a></h3><p>这个文档站是从<a href="https://github.com/yairm210/Unciv/tree/master/docs" target="_blank" rel="noreferrer">主仓库的 &#39;docs&#39; 文件夹</a>自动构建的， 所以要改进它，你通常要在本地 Unciv 克隆的分支上处理那些文件。</p><p>然而，典型的编辑器预览并不能作为权威，因为文件要经过构建流程处理。 在 UncivCN 分支，文档站使用 VitePress（英文区复用 <code>docs/</code>，中文区在 <code>docs/zh/</code>）。 要彻底检查，请在本地运行构建并在浏览器中查看结果：</p><ul><li>一键构建 + 预览：双击 <code>docs-vitepress/build.bat</code>（Windows）</li><li>或手动执行： <ul><li><code>./gradlew desktop:generateDocs</code>（生成 uniques 等 Kotlin 文档）</li><li>在 <code>docs-vitepress/</code> 下 <code>npm ci &amp;&amp; npm run docs:build</code></li><li>产物在 <code>docs-vitepress/.vitepress/dist</code>，可用 <code>npm run docs:preview</code> 预览（地址 <code>http://localhost:4173/Unciv/</code>）</li></ul></li></ul><h3 id="清理过时文件" tabindex="-1">清理过时文件 <a class="header-anchor" href="#清理过时文件" aria-label="Permalink to &quot;清理过时文件&quot;">​</a></h3><p>时不时地，Unciv 会升级主要工具版本——主要是 Gradle、Android SDK Platform 和 Android SDK Build-Tools。 新版本和支持文件会自动下载，但旧版本不会自动清理，中间构建文件也不会。 这可能会在你的系统上留下几 GB 的死文件。如果它们烦到你了，可以这样清理：</p><ul><li>从 SDK manager 移除过时的 Android SDK Platform 和 Build-Tools 版本（记住所有项目共享这些，所以如果还有其他项目，保留它们的要求）。</li><li>关闭 Android Studio 后（Windows 上可能还得手动结束残留的 Gradle daemon）： <ul><li>从 Unciv/.gradle、~/.gradle/caches（Windows 上为 %HOME%.gradle\\caches）和 ~/.gradle/daemon 删除以过时 Gradle 版本命名的子文件夹</li><li>要彻底但更昂贵的清理，把 ~/.gradle/caches 整个清掉，只保留标记文件。 这会强制下一次 gradle 同步重新下载大量支持文件，但这样也能清掉对已淘汰的 kotlin、Gdx 等支持库的残留。</li></ul></li></ul><p>另外，git 把&quot;你的改动安全&quot;置于效率之上，到了极端的程度，导致一些膨胀。 <code>git gc</code> 会自动做，但很克制，手动运行也无妨。 更彻底的做法是偶尔在 Studio 的终端（或 Unicv 项目文件夹内的任何 shell）运行 <code>git gc --prune=now --aggressive</code>， 但要先确保清理掉所有过时的分支，且剩余分支与它们对应的远程分支同步（如果只有本地分支，则基于 master）。</p><h3 id="uncivserver" tabindex="-1">UncivServer <a class="header-anchor" href="#uncivserver" aria-label="Permalink to &quot;UncivServer&quot;">​</a></h3><p>源码中自带的简易多人服务器主机可以像游戏本体一样调试或运行：</p><ul><li>在 Android Studio 中，Run &gt; Edit configurations。 <ul><li>点击 &quot;+&quot; 添加新配置</li><li>选择 &quot;Application&quot; 并命名为 &quot;UncivServer&quot;</li><li>模块设为 <code>Unciv.server.main</code>（Bumblebee 及以下版本的 Studio 为 <code>Unciv.server</code>），主类设为 <code>com.unciv.app.server.UncivServer</code>，工作目录设为 <code>&lt;repo_folder&gt;/android/assets/</code>，点 OK 关闭窗口。</li></ul></li><li>选择 UncivServer 配置，点击绿色箭头运行！或者像上面那样开始调试会话。</li></ul><p>要构建 jar 文件，参见<a href="#不用-android-studio">不用 Android Studio</a>，把 &#39;desktop&#39; 换成 &#39;server&#39;。即运行 <code>./gradlew server:dist</code>，完成后到 /server/build/libs/ 找 UncivServer.jar</p>',44)])])}const k=l(n,[["render",c]]);export{b as __pageData,k as default};
